        V.text(g, String(i + 1).padStart(2, '0'), sx + 12, y + (lh - 6) / 2 + 4, { size: 11, font: 'mono', color: col });
        V.text(g, L.t, sx + 38, y + (lh - 6) / 2 + 5, { size: 13, weight: on ? 600 : 400, color: on ? C.ink : C.muted, maxW: sw - 46 });
