    const f3 = root.querySelector('#fig-conta');
    const stage3 = f3.querySelector('.la-fig-stage');
    const fitH3 = () => { const w = stage3.clientWidth || 800; stage3.style.height = (w < 560 ? 460 : 400) + 'px'; };
