        g.fillStyle = V.alpha(C.a, 0.12); g.fillRect(NX(0.7), ny - 46, NX(1.2) - NX(0.7), 52);
        V.line(g, NX(1), ny - 46, NX(1), ny + 6, { color: V.alpha(C.a, 0.6), lw: 1, dash: [3, 3] });
