        V.text(g, narrow ? 'wₖ·λ·ℒₖ PER POSITION' : 'WEIGHTED CONTRIBUTION wₖ·λ·ℒₖ', G0.x, G0.y - 12, { size: 10.5, font: 'mono', color: C.muted, maxW: G0.w });
        const slot = G0.w / 5, bw2 = slot * 0.5;
