        if (stepN % 20 === 0) { let c = 0; for (let i = 0; i < D.n; i++) { const p = fwd(D.X[i][0], D.X[i][1]); if ((p > 0.5) === (D.Y[i] === 1)) c++; } acc = c / D.n; rAcc.set(Math.round(acc * 100) + '%'); }
