        const scTxt = scIn >= 1 && Math.abs(scIn - Math.round(scIn)) < 1e-9 ? ni(scIn) : sci(scIn, 0);
        const row0 = drawRow(0, R.x, scIn, scTxt, 'input x', C.a, 1);
