            g.lineCap = 'round'; V.line(g, o[0], o[1], ft[0], ft[1], { color: V.alpha(col, 0.45), lw: 8 }); g.lineCap = 'butt';
            V.dot(g, ft[0], ft[1], 3.5, col);
