        rms: { lab: 'RMSNorm gain: [T, d] ⊙ [d]', A: [4, 6], B: [6], op: '⊙', note: 'Each coordinate has its own learned gain, the same for every token.', recipe: 'every RMSNorm in the three recipes' },
