        ext: { lab: 'outer product: [K, 1] ⊙ [1, N]', A: [5, 1], B: [1, 6], op: '⊙', note: 'Both operands stretch: out comes a whole rank-1 matrix.', recipe: 'the v·kᵀ write of linear attention' },
        mhc: { lab: 'mHC: post_mix ⊗ y', A: ['T', 4, 1], B: ['T', 1, 4096], op: '⊙', note: 'Each of the 4 streams receives the output y with its own weight: an outer product with batch axis T.', recipe: 'GLM and DeepSeek (mHC, 4 streams)' },
        err: { lab: 'per-head gate: [T, 64, 128] ⊙ [64]', A: ['T', 64, 128], B: [64], op: '⊙', note: "Aligning from the right, 64 meets 128: error. (Illustrative, inspired by KDA's per-head gate.)", recipe: 'illustrative' },
        fix: { lab: 'fixed: [T, 64, 128] ⊙ [64, 1]', A: ['T', 64, 128], B: [64, 1], op: '⊙', note: 'With A[:, None], 64 matches 64 and the 1 stretches over the 128 channels, with no copy (stride 0).', recipe: 'illustrative' },
        e_gemm: { lab: 'einsum · mk,kn->mn (GEMM)', es: 'mk,kn->mn', ops: ['X', 'W'], sz: { m: 32, k: 4096, n: 12576 }, flops: 'FLOPs = 2·m·k·n = 2 × 32 × 4,096 × 12,576 ≈ 3.3 GFLOP', note: 'k is in both inputs and not in the output: it is summed. It is the GEMM Y = XW with the shapes of the KDA in_proj (per GPU) in a decode step with M = 32.', recipe: 'GLM' },
        e_att: { lab: 'einsum · thd,shd->hts (scores)', es: 'thd,shd->hts', ops: ['q', 'k'], sz: { t: 'T', h: 64, d: 256, s: 'T' }, flops: 'FLOPs = 2·t·s·h·d = 32,768·T² (T = 8,192: ≈ 2.2 TFLOP per layer)', note: "h is in both inputs and in the output: it is batch, and each head does its own math. d is summed. Out comes one [T, T] per head (shapes of GLM's MLA: 64 heads × 256).", recipe: 'GLM' },
        e_ds: { lab: 'einsum · bsgd,grd->bsgr (DeepSeek)', es: 'bsgd,grd->bsgr', ops: ['o', 'wo_a'], sz: { b: 'B', s: 'T', g: 8, d: 4096, r: 1024 }, flops: 'FLOPs = 2·b·s·g·d·r = 67.1 MFLOP per token (b·s = 1)', note: 'g is batch: each of the 8 groups (8 heads × 512 = 4096) has its own 1024 × 4096 matrix. d is summed. At TP=2, each GPU gets 4 groups.', recipe: 'DeepSeek-V4 (o_groups = 8, o_lora_rank = 1024)' },
