        slice: { lab: 'slice', shape: [3, 2], strides: [4, 1], off: 1, txt: 'x[:, 1:3]   → offset 1' },
        expand: { lab: 'expand', shape: [3, 4], strides: [0, 1], off: 0, txt: 'x[0].expand(3, 4)   → stride 0' },
        kpool: { lab: 'kpool page (GLM)' },
