      let H = null;
      const ctl = UI.controls(fig);
      UI.seg(ctl, { label: 'Mode', options: Object.keys(MODES).map((k) => ({ v: k, label: MODES[k].lab })), value: 'contig', onChange: (v) => { S.m = v; S.rain = -1; kp.forEach((e) => show(e, v === 'kpool')); applyH(); H.redraw(); } });
      const tgl = UI.toggle(ctl, { label: 'kernel with dense stride (the bug)', value: true, onChange: (v) => { S.bug = v; S.rain = -1; H.redraw(); } });
      const sB = UI.slider(ctl, { label: 'block b', min: 0, max: 551, step: 1, value: 58, fmt: (v) => String(v), onInput: (v) => { S.b = v; H.redraw(); } });
      const btn = UI.button(ctl, '▶ 552 cards', () => { S.rain = S.t; H.redraw(); });
