        g.fillStyle = V.alpha(C.red, 0.35); g.fillRect(x0, oy - 3, Math.max(3, (10 / NBLK) * (x1 - x0)), oh + 6);
        V.line(g, ox(b), oy - 6, ox(b), oy + oh + 6, { color: C.a, lw: 2 });
