        if (S.bug && b < Z && b > 0) { const ownX = xAt(own); g.setLineDash([4, 3]); V.box(g, ownX - 6, zy - 3, 12, zh + 6, { r: 3, stroke: C.a, lw: 1.5 }); g.setLineDash([]); }
