          if (!Number.isFinite(v)) { st = 'overflow → +∞'; sc = C.red || C.c; }
          else if (v === 0) { st = 'underflow → 0'; sc = C.red || C.c; }
          else if (x < mn) { st = 'subnormal'; sc = C.d; }
