        const form = `bytes = ${S.n > 1 ? bi(S.n) + ' × ' : ''}${bi(S.R)} × ${bi(S.C)} × ${f.bits}/8${z.sc ? ` + scales (${f.how})` : ''} · ${two(z.bpe)} bits per element`;
        const nF = wrap(g, form, pad, yF + 22, w - 2 * pad, 16, { size: 11.5, font: 'mono', color: C.text2 || C.muted });
