        V.text(g, `${bi(rowBits)} bits`, Math.min(w - pad, x + 6), cy + chh / 2 + 4, { size: 11, font: 'mono', color: C.muted, align: x + 60 > w - pad ? 'right' : 'left' });
        const note = S.fmt === 'exl3'
