        const colOf = (i) => { if (vert) return 0; const r = rowOf(i), c = i % cols; return r % 2 ? cols - 1 - c : c; };
        const pos = L.map((_, i) => [padX + colOf(i) * dx, top + rowOf(i) * rh]);
        const FO = vert ? [[-15, 0], [15, 0]] : [[0, -17], [0, 17]];
