        V.text(g, 'tokens in the sentence', px, py - 12, { size: 11, color: C.muted });
        V.text(g, 'merges learned →', px + pw / 2, py + ph + 16, { size: 11, color: C.muted, align: 'center' });
        V.text(g, '0', px, py + ph + 16, { size: 11, color: C.muted, font: 'mono' });
