        merges.push({ a, b, ab: a + b, id: 256 + k, n: pc[0][1] });
        states.push(seg.map((s) => { const o = []; for (let i = 0; i < s.length; i++) { if (i < s.length - 1 && s[i] === a && s[i + 1] === b) { o.push(a + b); i++; } else o.push(s[i]); } return o; }));
