          V.text(g, '"role": "' + role + '"', cx + 10, y + 17, { size: 11.5, font: 'mono', color: C.b, maxW: cw - 18 });
          V.text(g, '"content": "' + txt + '"', cx + 10, y + 34, { size: 11.5, font: 'mono', color: C.ink, maxW: cw - 18 });
