      T.el.style.minHeight = narrow3 ? '230px' : '250px';
      T.el.style.padding = narrow3 ? '34px 10px 6px' : '40px 10px 6px';
      T.explode(1.6);
      // a fatia destacada sobe para fora da pilha (como uma carta puxada do baralho)
