        V.arrow(g, cxm, rowsY[0] + barH / 2 + 2, cxm, rowsY[1] - barH / 2 - (wide ? 3 : 20), { color: V.alpha(C.muted, 0.7), lw: 1.4, head: 6 });
        V.text(g, 'W_Q', cxm + 8, (rowsY[0] + rowsY[1]) / 2 + (wide ? 0 : -6), { size: 11, font: 'mono', color: C.muted });
