          if (padH) { hatch(g, x, rowsY[3] - barH / 2, Math.max(1, segW - (segW > 4 ? 1 : 0)), barH, V.alpha(C.muted, 0.7), 3); continue; }
          g.fillStyle = V.alpha(bad && !M.pad3 ? C.c : rankCol[rk], hh % 2 ? 0.4 : 0.65);
