        if (i === 1) L.push(E('ple.ple_embedding.ngram_embedding.shard_{0..127}.weight', '[2500012, 160]', 'F8', 'ple'), E('ple.{key_proj,value_proj,conv1d,norm_*}', '[10240,2560]·[2560,2560]·…', 'BF16', 'ple'));
