            T(g, e.s + (e.t ? '  ' + e.t : ''), lR.x + lR.w - 2, y + 15, { size: fit(g, e.s + (e.t ? '  ' + e.t : ''), shW, 11.5, 'mono'), font: 'mono', align: 'right', color: on ? mc : C.muted, maxW: shW });
