      UI.toggle(ctl, { label: 'MoE: 288 experts, top-8 (GLM)', value: false, onChange: (v) => { S.moe = v; upd(); } });
      UI.seg(ctl, { label: 'Peak', options: [{ v: 125, label: 'BF16 ~125 TFLOPS' }, { v: 500, label: 'FP4×FP8 ~4×' }], value: 125, onChange: (v) => { S.peak = v; upd(); } });
