        V.text(g, fit(g, narrow ? 'one Qwen GPU · 121.69 GiB' : 'memory of one Qwen GPU (TP2, GMU 0.835) · 121.69 GiB', w - 2 * pad, 11.5, 'mono'), pad, 18, { size: 11.5, font: 'mono', color: C.muted });
        const by = 28, bh = 26, bW = w - 2 * pad;
