          const txt = lbl ? lbl + ' ' + nf(sg[1], sg[1] < 10 ? 2 : 1) : '';
          if (txt && tw(g, txt, 11, 'mono', 600) < ww - 8) V.text(g, txt, x + 6, by + bh / 2 + 0.5, { size: 11, font: 'mono', weight: 600, color: sg[0].startsWith('outside') ? C.ink : onInk(), base: 'middle' });
