        const cw = narrow ? Math.max(24, Math.min(30, Math.floor((w - 104) / 8) - 2)) : 36;
        const ch = narrow ? 21 : 23;
        const st = cw + 2, sth = ch + 2;
        const fsz = cw >= 32 ? 12.5 : 11.5;
        const jHi = Math.floor(t / 0.9) % T0;
