        const gA1 = narrow ? 30 : 42, gA2 = narrow ? 26 : 36;
        let xIn, yIn, xR, yA, yB, yCnt;
        if (!narrow) { xIn = 16; yIn = 60; xR = 16 + 5 * st + 60; yA = 52; yB = 226; yCnt = 398; }
        else { xIn = 14; yIn = 40; xR = 14; yA = 188; yB = 364; yCnt = 540; }
