            V.text(g, 'S', x, sy + 0.5, { size: 11, font: 'mono', align: 'center', base: 'middle', color: C.ink, weight: 600 });
            if (c < nC) V.line(g, x + 13, sy, x + S.C * bw - 13, sy, { color: V.alpha(C.a, 0.35), lw: 1.2, dash: [3, 4] });
