          const mY = sy + 30; const avail = Math.min(cwid, w * 0.5, (h - 64) - 46 - mY);
          const cs = Math.max(6, Math.min(narrow ? 18 : 24, avail / S.C - 2));
          const mw = S.C * (cs + 2);
          const mX = V.clamp(cx0 + cwid / 2 - mw / 2, mx, w - mx - mw);
          const a = V.ease.out(Math.min(1, el * 3));
