      UI.slider(ctl, { label: 'Context', min: 10, max: 20, step: 0.25, value: S.lg, fmt: (v) => nf(Math.round(2 ** v)) + ' tok', onInput: (v) => { S.lg = v; } });
      const cv = (nm) => 'var(--viz-' + nm + ')';
