        b1: (t, s, c, fs, v) => 'E' + sub(c) + '(' + t + '→' + s + ') = ' + (fs.length > 1 ? fs.join(' × ') + ' = ' : '') + v,
        b2: (s, t, l, m) => 'L' + sub(s) + sub(t) + ' = ' + l + '   ·   M' + sub(s) + sub(t) + ' = ' + m,
        b3: (s) => 'computing row ' + s + ' of T from rows 0…' + Math.max(0, s - 1),
        b4: (s, y, vp) => 'row ' + s + ':  Y = [' + y + ']  →  V′ = [' + vp + ']',
