        V.rr(g, bx, by, Math.max(4, X(state) - bx), bh, 6); g.fillStyle = V.alpha(M.n > 1 ? C.a : C.muted, 0.8); g.fill();
        if (M.n > 1) { const xs = X(single); V.line(g, xs, by - 3, xs, by + bh + 3, { color: C.ink, lw: 2 }); }
