          V.box(g, b2.x, b2.y, boxW, 58, { r: 10, fill: V.alpha(C.d, 0.08), stroke: V.alpha(C.d, stateUsed.conv.length ? 0.9 : 0.35), lw: stateUsed.conv.length ? 1.8 : 1 });
