        V.text(g, causal ? (q === 0 ? 'causal: the corner sees only itself' : `causal: sees only ${vis} patches (the earlier ones)`) : 'bidirectional: sees all 64 patches', gx, gy + G + 20, { size: 12.5, font: 'mono', color: causal ? C.c : C.a, maxW: G + (mob ? 0 : 60) });
