          V.matrix(g, { x: px, y: py + 124, w: Math.min(pw, 240), h: 80, data: V.randMatrix(6, 16, 11), cmap: 'div', gap: 1, r: 1 });
          V.text(g, `[36 × ${M.d}]`, px + Math.min(pw, 240) + 8, py + 170, { size: 12, font: 'mono', color: C.muted });
