            if (arrived) { for (let s2 = 0; s2 < 4; s2++) { g.fillStyle = V.cmap(vecs[idx][s2], 'div'); g.fillRect(tx0 + 2 + (s2 * (sgw - 4)) / 4, vy + 3, (sgw - 4) / 4 - 1, vh - 6); } }
