            V.line(g, X - 12, Y, X + 12, Y, { color: col, lw: 1.5 }); V.line(g, X, Y - 12, X, Y + 12, { color: col, lw: 1.5 });
            if (lab === 'μ⁺') tag(g, lab, X + 12, Y - 16, col, { size: 12 }); else tag(g, lab, X - 12, Y + 18, col, { size: 12, align: 'right' });
