          const M = S.ds ? sinkhorn(D.raws[k]) : D.raws[k], p = D.posts[k], y = D.ys[k];
          const mix = [0, 1, 2, 3].map((i) => [0, 1, 2, 3].reduce((s, j) => s + M[j][i] * Hc[j], 0));   // H'ᵢ = Σⱼ comb[j][i]·Hⱼ
          const after = mix.map((v, i) => v + p[i] * y);                                                   // + postᵢ·y
