        V.text(g, 'p̄ = mean(post) = ' + fmt(st.pbar, 2) + '   ·   y·r = ' + fmt(st.y, 2), px0, iy + 38, { size: 11, color: C.d, maxW: pw });
        // ---------- writers timeline
