          const nl = Math.min(2, splitLines(g, b, bw - 8, { size: narrow ? 11 : 12, font: 'mono' }).length);
          wrap(g, b, x + bw / 2, py + (nl > 1 ? 14 : 21), bw - 8, 13, { size: narrow ? 11 : 12, align: 'center', color: C.ink, font: 'mono', maxLines: 2 });
