        const ty = V.lerp(bottom - 6, top + 6, tp);
        const tx = pad + rowLab + (towerW - rowLab) * (0.5 + 0.28 * Math.sin(tp * Math.PI * 4));
        V.glow(g, tx, ty, 14, C.d, 0.9); V.dot(g, tx, ty, 4, C.d);
