        core: { lab: 'core', ab: 'core', idle: 2.0, site: 'o' },
        o: { lab: 'output', ab: 'out', mib: 12 },
        ag1: { lab: 'AG + glue', ab: 'AG', idle: 2.4, site: 'a' },
        sh: { lab: 'shared', ab: 'sh.', mib: 12 },
