            hatch(g, x + 1, y + 1, bw - 2, laneH - 2, V.alpha(C.muted, 0.55), 5);
            if (bw > 16) V.text(g, b.size, x + bw / 2, y + laneH / 2 + 1, { size: 11, align: 'center', base: 'middle', color: C.muted, font: 'mono' });
