        if (!sm) V.text(g, 'reserved virtual addresses', Math.min(w - pad, pad + ex.size * pu + 64), y2 + laneH / 2 + 4, { size: 11, color: C.muted });
        const statsY2 = sm ? y2 + laneH + 14 : y2 - 12;
