          if (hz) { V.box(g, lx, ly - 8, 11, 11, { r: 3, fill: V.alpha(c, 0.15), stroke: V.alpha(c, 0.6), lw: 1 }); hatch(g, lx, ly - 8, 11, 11, V.alpha(c, 0.7), 4); }
          else V.box(g, lx, ly - 8, 11, 11, { r: 3, fill: c });
