        const padded = rows.filter((r) => r.s != null);
        const pad = padded.length ? padded.reduce((a, r) => a + (r.s - r.T) / r.s, 0) / padded.length : 0;
        R = { sizes, rows, log, eager: eager.length, pad, lens, teto };
