          if (black) { fill = C.dark ? 'rgba(0,0,0,0.55)' : 'rgba(30,30,40,0.85)'; stroke = n.k === 'attn' ? C.c : C.f; }
          if (fused && (k === 4 || k === 5)) { fill = V.alpha(C.e, 0.3); stroke = C.e; }
