          if (i >= 1) V.text(g, black ? 'fake → ' + n.sh : n.sh, p.x + nw / 2, p.y + 35, { size: 11, font: 'mono', align: 'center', color: black ? '#dddddd' : C.muted, maxW: nw - 6 });
