            if (b.s >= ph) return;
            const xa = X(b.s), xb = X(Math.min(b.e, ph)), yy = ly + b.lane * lh + 3;
            g.fillStyle = V.alpha(C.red || '#FB2C36', 0.07); g.fillRect(xa, yy, xb - xa, lh - 6);
            hatch(g, xa, yy, xb - xa, lh - 6, V.alpha(C.muted, 0.55), 6);
