      UI.seg(ctl, { label: 'Threshold', options: [{ v: 0, label: '0 (off)' }, { v: 1024, label: '1024' }, { v: 4096, label: '4096' }], value: 0, onChange: (v) => { S.thr = v; plan(); } });
