        const locoW = narrow ? 38 : 50, gapW = narrow ? 12 : 16;
        const wagW = B * chip + (B - 1) * 2 + 12;
        const perRow = Math.max(1, Math.floor((w - 20 - locoW - 8 + gapW) / (wagW + gapW)));
        const rowH = chip + 46;
