      s1.queue = [5, 6, 7, 8, 9, 10]; s1.table = [['h1', 1], ['h2', 2], ['h3', 3]]; s1.q = 13; s1.hh = 0;
      s1.req = { name: 'A', n: 13, blocks: [['S1', 1, 'miss'], ['S2', 2, 'miss'], ['a', 3, 'miss'], ['a·', 4, 'part']] };
