      s6.queue = [4, 10, 9, 8, 7, 6]; s6.table = [['h1', 1], ['h2', 2], ['h3', 3], ['h4', 4], ['h5', 6], ['h6', 7], ['h7', 8], ['h8', 9], ['h9', 10]];
