            g.beginPath(); g.moveTo(fx, ly + 2); g.lineTo(fx - 5, ly - 6); g.lineTo(fx + 5, ly - 6); g.closePath(); g.fillStyle = col; g.fill();
            if (!narrow) V.text(g, nf(c.per[L.k]), fx + 7, ly - 1, { size: 11, font: 'mono', color: C.ink });
