        const maxT = T0 + (S.n + ADD) / R;
        V.text(g, 'TTFT per request (3 runs of a cold → warm pair)', cx0, 18, { size: 11.5, color: C.muted, maxW: chartW });
        const slot = chartW / 3, bw = Math.min(46, slot / 2 - 14);
