      V.text(g, clip(g, JSON.stringify(sim.rs), w - 52 - 90, narrow ? 11 : 12), fx + 84, py + 20, { size: narrow ? 11 : 12, font: 'mono' });
      V.text(g, 'content', fx, py + 42, { size: 11, font: 'mono', color: C.a });
