      const cl = wrapChars(g, JSON.stringify(content), w - 52, lsz, 'mono', 400);
      cl.slice(0, 3).forEach((l, i) => V.text(g, l, fx, py + 38 + i * 15, { size: lsz, font: 'mono', color: leak && n > 2 ? C.red : C.ink }));
      let yy = py + 44 + Math.min(3, cl.length) * 15;
