        const shares = [ea[0], ea[1], ea[2]];
        const ssum = shares.reduce((a, b) => a + b, 0) + ea[3] * 16;
        shares.forEach((s) => pa.push(rest * s / ssum));
        pa.push(rest * (ea[3] * 16) / ssum);
