        [0, 0.5, 1, 1.5].forEach((v) => V.text(g, v.toFixed(1), gx + (v / 1.5) * GW, gy + GH + 15, { size: 11, align: 'center', font: 'mono', color: C.muted }));
        V.line(g, gx, gy + 3, gx + GW, gy + 3, { color: C.b, lw: 2, dash: [2, 4] });
