      const pws = block.map((s) => pill(g, s, 0, 0, { size: narrow ? 11 : 12.5, dry: true, minW: narrow ? 40 : 54 }));
      const totalW = pws.reduce((a, b) => a + b, 0) + 6 * (block.length - 1);
