            if (i === 6) col = C.a;
            else if (i >= 3 && j === 0) col = C.a;
            if (i >= 4 && i <= 5 && j === 1) { col = RED(); mood = 'sad'; }
            if (i === 5 && j >= 2) { alpha = Math.max(0.25, 1 - el * 0.8); mood = 'sad'; col = C.muted; }
            tokChar(g, cx(c), yc + dy, s, col, { mood, alpha });
            g.globalAlpha = alpha;
