          const px = V.lerp(sx, x0, V.ease.out(f1)), py2 = V.lerp(sy, y0, V.ease.out(f1));
          if (f1 < 1) { V.line(g, V.lerp(sx, px, 0.6), V.lerp(sy, py2, 0.6), px, py2, { color: V.alpha(C.ink, 0.5), lw: 1.5 }); V.dot(g, px, py2, 3, C.ink); return; }
          g.globalAlpha = fade;
