            V.rr(g, sx, y + 0.4, sw, Math.max(1.5, lh - 1.4), 2); g.fillStyle = V.alpha(tcol(i), tapped ? 0.95 : 0.45); g.fill();
            if (tapped) tapPos.push([sx + sw + 7, y + lh / 2]);
