            const cellH = (h - 4) / 16;
            g.fillStyle = V.cmap(v * (on ? (0.7 + 0.3 * Math.sin(t * 3 + c)) : 0.8), 'seq');
            g.fillRect(x + 2 + c * cw, y + 2 + r * cellH, cw - 2, cellH - 1);
