          for (let c = 0; c < Math.min(nC, Math.floor(prog) + 1); c++) { const px = x + 4 + (c + 0.5) * cw, py = y + 4 + (path[c] + 0.5) * rh; c ? g.lineTo(px, py) : g.moveTo(px, py); }
