            for (let q = 0; q < p; q++) V.dot(g, cxx + cell / 2 + (q - (p - 1) / 2) * 5, cyy + cell - 4, 1.6, cc.m & (1 << q) ? cols[q] : V.alpha(C.muted, 0.25));
            const isSrc = tr.some((o) => o.r === r && o.k === k), isDst = tr.some((o) => o.d === r && o.k === k);
