        if (r.type === 'v1') return { k, ok: false, msg: pre + 'type RoCE v1 — the requested version is 2' };
        if (r.k === 'v6') return { k, ok: false, warn: true, msg: pre + 'global IPv6 — family ≠ AF_INET' };
