            V.text(g, 'port ' + pt + ' (f' + pt + ')' + (used ? '' : (narrow ? '' : ' · no cable: never list it')), N.x + 16, y + 15, { size: 11, weight: used ? 600 : 400, color: used ? C.ink : C.muted, maxW: nw - 30 });
