        let yy = py + 18;
        yy += para(g, 'governed by: ' + S.gov, m + 12, yy, w - 2 * m - 24, { size: 11.5, font: 'mono', color: C.a, lh: 15 });
        para(g, 'if wrong: ' + S.fail, m + 12, yy + 4, w - 2 * m - 24, { size: 11.5, color: C.c, lh: 15 });
