          V.box(g, X0, 22, colW, panelB - 22, { r: 12, fill: V.alpha(col, 0.05), stroke: V.alpha(col, 0.35), lw: 1 });
          V.text(g, lab, X0 + colW / 2, 13, { size: 12, weight: 600, color: col, align: 'center', maxW: colW });
