          chip(g, ICON[e.st] + (narrow && e.txtN ? e.txtN : e.txt), cx, cy, stCol(C, e.st), { align: 'right', maxW: chipW, size: narrow ? 11 : 11.5 });
          g.globalAlpha = 1;
