            if (gq === 8) { if (i >= 3) dashedBox(g, x, y, cs, cs, V.alpha(C.d, 0.7), 2); continue; }
            V.box(g, x, y, cs, cs, { r: 2, fill: V.alpha(GCOL(C)[gq], 0.38) });
