        const colsX = (lane, slot) => { const lx = 16 + lane * (lw + lgap); const blockW = cols * lc * 1.3 - lc * 0.3; return lx + (lw - blockW) / 2 + (slot % cols) * lc * 1.3; };
        const bandY = (slot) => Math.floor(slot / cols) * (hpl + 0.8) * lc * 1.1;
