          for (let s = 0; s < 4; s++) { const xx = gx + R - ((s + 0.5) * (2 * R)) / 4; g.lineTo(xx, gy + R - 5 * (s % 2 === 0 ? 1 : 0)); }
          g.lineTo(gx - R, gy + R); g.closePath(); g.fill();
          V.dot(g, gx - R * 0.35, gy - 2, 2.4, C.bg); V.dot(g, gx + R * 0.35, gy - 2, 2.4, C.bg);
