        const ua = wtext(g, r.a, rx + 24, py + 8, rw - 26, { size: asz, lh: alh, color: C.ink, weight: 600, maxLines: 2 });
        const ub = wtext(g, on ? r.b : '…', rx + 24, py + 8 + ua + 1, rw - 26, { size: bsz, lh: blh, font: 'mono', color: r.k === 'bad' && on ? C.c : C.muted, maxLines: 2 });
