            const r = Math.floor(k / per), j = k % per, full = (r + 1) * per <= ids;
            if (k >= shown) { V.box(g, cx + 1, cy + 1, cs - 2, cs - 2, { r: 2, fill: V.alpha(C.muted, 0.12) }); continue; }
            const isMla = j < MLA_850, col = isMla ? C.a : C.b;
