          let best = null, bd = 26;
          for (let i = 0; i < 5; i++) for (let j = 0; j < 5; j++) { const d = Math.hypot(H.pointer.x - SX(j), H.pointer.y - SY(i)); if (d < bd) { bd = d; best = [i, j]; } }
