          V.text(g, narrow ? B.sh : B.lab, bx + 12, y + bh / 2 + 1, { size: narrow ? 11 : 12, base: 'middle', color: C.ink, weight: cur ? 700 : 400, maxW: bwid - 44 });
          if (B.lock) lock(g, bx + bwid - 18, y + bh / 2, col);
