        let ratio = N / K; const clamped = ratio < 0.06 || ratio > 12;
        ratio = Math.max(0.06, Math.min(12, ratio));
        const ah = clamped ? Math.max(40, ahAll * 0.36) : ahAll;
        let bw = aw, bh = aw * ratio;
