          g.globalAlpha = f;
          V.line(g, xa, y, xb, y, { color: col, lw: 2 });
          V.line(g, xa, y - 5, xa, y + 5, { color: col, lw: 2 }); V.line(g, xb, y - 5, xb, y + 5, { color: col, lw: 2 });
          const lw0 = tw(g, label, 11.5, 'mono', 600);
