          if (S.eff) {
            const e = v / (d.lv[i] * d.agg[0]);
            pill(g, XC(i), Math.max(gy + 10, y - 26), br(e * 100, 0) + '%', e > 0.7 ? C.e : e > 0.4 ? C.d : C.c, { align: 'center', size: 11 });
          }
