          V.rr(g, x + 1, y, cW - 2, cH, 5); g.fill();
          g.strokeStyle = V.alpha(C.series[chunk % 6], 0.8); g.lineWidth = within === Math.floor(ph) && ph < c ? 2.4 : 1; g.stroke();
