          tfit(g, sigs(res.parts[s], sp >= 8 ? 5 : 7), lx, ly, Math.max(40, Math.min(c, perRow) * cW - 4), { size: 10.5, min: 8.5, font: 'mono', align: 'center', color: C.series[s % 6] });
