        g.fillStyle = V.alpha(C.a, 0.4); g.fillRect(x0, ly, Math.max(0, LX(c.res) - x0), lh);
        g.fillStyle = V.alpha(RED(), 0.4); g.fillRect(LX(c.res), ly, x1 - LX(c.res), lh);
