            if (s.fan) { const n = 4, mw = Math.min(16, (r.w - 20) / n - 4); for (let k = 0; k < n; k++) blob(g, r.x + r.w / 2 + (k - (n - 1) / 2) * (mw + 6), r.y + r.h - 14, mw * 0.45, C.series[k % 6], { t: t + k, seed: k }); }
