        S.bx += (tx - S.bx) * Math.min(1, dt * 3.5); S.by += (ty - S.by) * Math.min(1, dt * 3.5);
        blob(g, S.bx, S.by + Math.sin(t * 6) * 1.5, narrow ? 11 : 14, colOf(P.st[S.act].col), { t });
