        // cabeçalho
        V.text(g, md.name, pad, 20, { size: 14, weight: 700, color: C.ink, maxW: w - 2 * pad });
        V.text(g, 'q: What is 17 × 24?', pad, 40, { size: 12, font: 'mono', color: C.muted });
