                if (md.det === 'opd') { g.setLineDash([3, 2]); V.rr(g, x + cw * 0.18, by + bh * (1 - pT[j]), cw * 0.64, bh * pT[j], 3); g.strokeStyle = V.alpha(C.d, 0.95); g.lineWidth = 1.4; g.stroke(); g.setLineDash([]); }
