            g.beginPath(); Vc.forEach((v, j) => (j ? g.lineTo(colX(j), Yv(v)) : g.moveTo(colX(j), Yv(v)))); g.strokeStyle = V.alpha(C.b, 0.9); g.lineWidth = 2; g.stroke();
