      const rB = UI.readout(ctl, 'bytes/param', '—'), rT = UI.readout(ctl, 'total state', '—'), rX = UI.readout(ctl, 'vs. inference', '—'), rF = UI.readout(ctl, 'on one Spark', '—');
      const sum = (ps) => ps.reduce((s, p) => s + p[1], 0);
