      UI.toggle(ctl, { label: 'show the others', value: true, onChange: (v) => { S.all = v; } });
      const rP = UI.readout(ctl, 'peak', '—'), rN = UI.readout(ctl, 'now', '—'), rS = UI.readout(ctl, 'shape', '—');
