          let u = Math.random(), x = 0, acc = 0; for (let i = 0; i < NB; i++) { acc += q[i]; if (u <= acc) { x = xsB[i] + (Math.random() - 0.5) * dx; break; } }
          S.parts.push({ x, y: top - 6, v: 0, c0: Math.abs(S.mu - S.target[0]) < 0.05 && Math.abs(S.sig - S.target[1]) < 0.05 });
