      nocase(UI.slider(ctl, { label: 'proxy length bias', min: 0, max: 1, step: 0.1, value: S.b, fmt: (v) => fmt(v, 1), onInput: (v) => { S.b = v; clearTimeout(S.pending); S.pending = setTimeout(recompute, 60); } }));
      nocase(UI.seg(ctl, { label: 'Proxy', options: [{ v: '1', label: '1 RM' }, { v: 'media', label: 'mean of 4' }, { v: 'min', label: 'min of 4 (WCO)' }], value: '1', onChange: (v) => { S.ens = v; S.rt0 = -10; upd(); } }));
      const rK = UI.readout(ctl, 'BoN KL', '—'), rG = UI.readout(ctl, 'mean gold', '—'), rP = UI.readout(ctl, 'mean proxy', '—'), rL = UI.readout(ctl, 'mean length', '—');
      nocase(ctl);
      if (LA.onCleanup) LA.onCleanup(() => clearTimeout(S.pending));
      const toks = (l) => Math.max(20, Math.round(300 + 150 * l));
