      nocase(UI.seg(gM.el, { label: 'From step', options: [{ v: 0, label: '1' }, { v: 1, label: '2' }, { v: 2, label: '3' }, { v: 3, label: '4' }], value: 2, onChange: (v) => { S.step = v; S.seed = 0; S.t0 = H.t; sample(); } }));
      nocase(UI.slider(gM.el, { label: 'N continuations', min: 2, max: 16, step: 1, value: 4, fmt: (v) => String(v), onInput: (v) => { S.N = v; S.seed = 0; S.t0 = H.t; sample(); } }));
      UI.button(gM.el, '🎲 resample', () => { S.seed++; S.t0 = H.t; sample(); });
