            const ls = []; for (let i = 0; i < NA; i++) ls.push(L());
            const B = t0 + Math.max(...ls);
            for (let i = 0; i < NA; i++) { segs.push({ a: i, s: t0, e: t0 + ls[i], v: version }); idles.push({ a: i, s: t0 + ls[i], e: B + U }); sends.push({ a: i, t: B, st: 0 }); }
            ups.push({ s: B, e: B + U, v: ++version });
