          traj.sort((x, y) => x.e - y.e);
          // aprendiz: consome lotes de 2 trajetórias quando ocioso
          const queue = []; let lt = 0, ver2 = 0, k = 0;
          const verHist = [{ t: 0, v: 0 }];
