      const ZS = [0.76, 0.72], SR = 0.17;
      const Rf = (x, y) => Math.exp(-((x - ZS[0]) ** 2 + (y - ZS[1]) ** 2) / (2 * SR * SR));
      const SD = 0.07, SP = 0.06;
      const D0 = [0.27, 0.3], CREF = [0.28, 0.32];
      const rng = V.rng(57);
