        cell(hx0, my0 + 14, cs, 2, C.b); cell(hx0, my0 + 14 + chh + 4, cs, Math.round(s * 10) / 10, C.b);
        const lx0 = hx0 + cs + 22;
        V.text(g, '=', lx0 - 11, my0 + chh + 20, { size: 15, color: C.ink, align: 'center' });
        const lg = [2 + 0.2 * s, 2 - 0.2 * s, s];
