          const row = []; const ls = Math.log(SMAX) - (r + 0.5) / HR * (Math.log(SMAX) - Math.log(SMIN));
          for (let c = 0; c < HC; c++) { const v = Math.log(loss((c + 0.5) / HC, ls) + 1e-3); row.push(v); mn = Math.min(mn, v); mx = Math.max(mx, v); }
