        cols.forEach((c, k) => V.text(g, c, cxs[k] + (cwF[k] * M.w) / 2, M.y + 9, { size: 11, font: 'mono', color: k >= 3 && i < k - 2 ? V.alpha(C.muted, 0.5) : C.muted, align: 'center', weight: 600 }));
        const wmax = Math.max(...D.rows.map((r) => r.w));
