          cell(0, r.s, { color: stc });
          cell(1, r.a);
          cell(2, fmt(r.R, 2));
          const fillIn = (stepIdx) => (i > stepIdx ? 1 : i === stepIdx ? V.clamp((el - k * 0.1) / 0.35, 0, 1) : 0);
          const fV = fillIn(1), fA = fillIn(2), fW = fillIn(3);
