        const lab = narrow ? 52 : 120;
        V.text(g, narrow ? 'raw' : 'raw weight', 10, ty + 11, { size: 11, color: C.muted, base: 'middle' });
        V.text(g, narrow ? 'norm.' : 'normalized', 10, ty + 33, { size: 11, color: C.muted, base: 'middle' });
        const tcw = (w - 20 - lab) / 4;
