        const rad = (n) => (n.kind === 'buddy' ? s * 0.62 : n.kind === 'doc' ? s * 0.55 : n.kind === 'box' ? 18 : n.kind === 'cands' || n.kind === 'pair' ? 20 : 14);
        // arestas
        const nE = meth.edges.filter((e) => !e[5]).length;
