      UI.slider(ctl, { label: 'self-confidence s', min: 0, max: 1, step: 0.05, value: 0.5, fmt: (v) => fmt(v, 2), onInput: (v) => { S.s = v; need = true; } });
      UI.slider(ctl, { label: 'truth advantage v', min: 0, max: 3, step: 0.1, value: 0.8, fmt: (v) => fmt(v, 1), onInput: (v) => { S.v = v; need = true; } });
      UI.seg(ctl, { label: 'Scenario', options: [{ v: 'certa', label: 'majority starts right' }, { v: 'errada', label: 'majority starts wrong' }], value: 'certa', onChange: (v) => { S.scen = v; need = true; } });
      const rM = UI.readout(ctl, 'final majority', '—'), rT = UI.readout(ctl, 'generated tokens', '—'), rC = UI.readout(ctl, 'matching self-consistency', '—');
