            const ey = sy + 44;
            V.text(g, narrow ? 'chosen' : 'chosen = C (5)', candX(2), ey, { size: 12, font: 'mono', weight: 700, color: C.a, align: 'center' });
            V.text(g, narrow ? 'rejected' : 'rejected = B (2)', candX(1), ey, { size: 12, font: 'mono', weight: 700, color: RED(), align: 'center' });
