        V.text(g, 'python ▸ exec' + (Math.floor(t * 2.5) % 2 ? '▌' : ''), exX + 10, exY + 17.5, { size: 11.5, font: 'mono', weight: 600, color: C.ink, base: 'middle', maxW: exW - 16 });
        // tentativas
