        const gy0 = topH + (narrow ? 30 : 20), gx0 = 50, gx1 = narrow ? w - 20 : w * 0.6, gy1 = narrow ? h - 172 : h - 34;
        const GX = (r) => gx0 + r * (gx1 - gx0), GY = (v) => gy1 - v * (gy1 - gy0);
