            if (attn) V.dot(g, x + cw / 2, by + rowH / 2 - 1, Math.min(3, cw / 3), C.c);
            V.box(g, x + 0.5, by + rowH + 2, cw - 1, rowH - 2, { r: 2, fill: V.alpha(colF[mlpF], 0.6 + flash) });
            geo.push({ x, y: by, w: cw, h: 2 * rowH + 2, L, attn, mlpF });
