        g.lineTo(gx0 + HB * bwid, gy0 + gh);
        g.strokeStyle = V.alpha(C.ink, 0.85); g.lineWidth = 1.6; g.lineJoin = 'miter'; g.stroke();
        const X = (v) => gx0 + ((v + HR) / (2 * HR)) * gw;
        [-1, 1].forEach((sg) => { const xx = X(sg * o.c); V.line(g, xx, gy0 - 4, xx, gy0 + gh, { color: C.d, lw: 2 }); });
        for (let q = -7; q <= 7; q++) { const xx = X((q * o.c) / 7); V.line(g, xx, gy0 + gh + 2, xx, gy0 + gh + 8, { color: C.d, lw: 1 }); }
        V.text(g, '±clip ' + fmt(o.c, 1) + 'σ and the 15 grid levels', X(0), gy0 + gh + 22, { size: 10.5, align: 'center', color: C.d });
        V.box(g, gx0, gy0 + gh + 30, 9, 9, { r: 2, stroke: V.alpha(C.ink, 0.85), lw: 1.6 }); V.text(g, 'generic (outline)', gx0 + 13, gy0 + gh + 38, { size: 10.5, color: C.muted });
        V.box(g, gx0 + 128, gy0 + gh + 30, 9, 9, { r: 2, fill: V.alpha(C.c, 0.7) }); V.text(g, fit(g, 'domain (8% ~4× larger)', gw - 141, 10.5), gx0 + 141, gy0 + gh + 38, { size: 10.5, color: C.muted });
        // error curves
