        const px0 = cx0 + 40, pw = cw2 - 52, py0 = cy0 + 24, ph2 = ch2 - 62;
        V.line(g, px0, py0 + ph2, px0 + pw, py0 + ph2, { color: V.alpha(C.muted, 0.5), lw: 1 });
        V.line(g, px0, py0, px0, py0 + ph2, { color: V.alpha(C.muted, 0.5), lw: 1 });
