        cur.drift += (M.drift - cur.drift) * kk; cur.quant += (M.quant - cur.quant) * kk;
        // context
        V.text(g, 'next token after:', 16, 18, { size: 11, color: C.muted, weight: 600 });
        V.text(g, fit(g, '“' + c.qs + '”', w - 32, 13, 'mono', 600), 16, 38, { size: 13, font: 'mono', weight: 600 });
