      const S = { mode: 'A', maxL: 2, ri: 2, nA: 3, real: 16, fmtv: 'nv', mtp: true, q: [], bus: [], seen: {}, acc: 0, id: 0, tick: 0, waiting: 0 };
      let kNarrowHRef = () => 540;
